/* Public source headlines only. No credentials or AI API keys in the browser. */
titles.news=['DAILY AI SIGNALS','오늘의 소식에서 내일의 변화를 읽기','공식 발표의 원문 제목을 보고, 관심 분야와 연결해 보세요. 발표와 실제 보급은 다릅니다.'];
let newsData=null,newsError=false,newsFilter='all';
const newsRemote='https://raw.githubusercontent.com/Mespital/ApuDa/main/future-compass/dist/news.json';
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeArticleURL(v){try{const u=new URL(v);return u.protocol==='https:'&&['openai.com','blog.google','deepmind.google','www.anthropic.com'].includes(u.hostname)?u.href:null}catch{return null}}
function dateLabel(v){const d=new Date(v);return Number.isNaN(+d)?'날짜 미확인':new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function newsPage(){if(!newsData)return '<div class="empty" role="status">공식 출처의 소식을 불러오고 있습니다…</div>';const articles=newsData.articles.filter(a=>newsFilter==='all'||a.category===newsFilter);const stale=!newsData.last_success_at||Date.now()-Date.parse(newsData.last_success_at)>48*3600000;return `<div class="callout"><strong>뉴스를 읽는 세 가지 질문</strong><br>무엇이 가능해졌나요? · 실제 생활에 쓰이려면 무엇이 더 필요한가요? · 내가 배우는 과목과 어떻게 연결되나요?</div><section class="section"><div class="news-health"><span class="news-status ${newsError||stale?'warning':''}">${newsError?'연결 실패 · 저장된 소식':stale?'갱신 상태 확인 필요':'공식 RSS 수집'}</span><span class="mini">최근 수집 성공: ${dateLabel(newsData.last_success_at)} · 매일 오전 7시 수집 예정(한국시간)</span><button class="jobbutton" data-news-refresh>다시 확인</button></div><p class="mini">GitHub 예약 실행은 지연될 수 있습니다. 원문 제목을 표시하며 아래 분야 연결은 키워드 기반 탐색 힌트입니다.</p>${newsData.failures?.length?'<p class="note">일부 출처 수집 실패: '+newsData.failures.map(escapeHTML).join(' · ')+'. 이전 소식은 유지됩니다.</p>':''}<div class="filter"><button data-news-filter="all" class="${newsFilter==='all'?'active':''}">전체</button>${['AI·컴퓨팅','로봇·기기','교육·생활','안전·보안','과학·환경'].map(c=>`<button data-news-filter="${c}" class="${newsFilter===c?'active':''}">${c}</button>`).join('')}</div><div class="grid">${articles.length?articles.map(a=>{const url=safeArticleURL(a.url);return `<article class="card"><div class="news-meta"><span class="tag">${escapeHTML(a.category)}</span><span>${escapeHTML(a.source)} · ${dateLabel(a.published_at)}</span></div><h2 class="news-title">${url?`<a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(a.title)}</a>`:escapeHTML(a.title)}</h2><p class="mini">공식 출처 원문 제목 · 링크에서 발표 내용 확인</p><div class="requirements">관심 분야와 연결해 생각하기<br><button class="jobbutton" data-news-domain="${escapeHTML(a.domain||'ai')}">관련 직업과 공부 보기</button></div></article>`}).join(''):'<div class="empty">이 분류의 소식은 아직 없습니다. 전체 소식을 확인하세요.</div>'}</div></section>`}
async function refreshNews(){newsError=false;try{const response=await fetch(newsRemote+'?t='+Math.floor(Date.now()/300000),{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('feed');newsData=validateNews(await response.json());}catch{newsError=true;if(!newsData){try{const r=await fetch('news.json',{cache:'no-store'});newsData=validateNews(await r.json())}catch{newsData={articles:[],failures:['뉴스 파일 연결'],last_success_at:null}}}}if(page==='news')render()}
function validateNews(data){if(!Array.isArray(data.articles))throw Error('schema');return {...data,articles:data.articles.filter(a=>typeof a.title==='string'&&safeArticleURL(a.url)&&Number.isFinite(Date.parse(a.published_at))).slice(0,30)}}
try{const saved=JSON.parse(localStorage.getItem('future-compass-v2')||'{}');saved.subjects?.filter(v=>subjectOptions.includes(v)).forEach(v=>chosenSubjects.add(v));saved.activities?.filter(v=>activityOptions.includes(v)).forEach(v=>chosenActivities.add(v));saved.completed?.filter(v=>Number.isInteger(v)&&v>=0&&v<6).forEach(v=>completed.add(v));if(saved.route==='self')route='self';}catch{}
function saveProgress(){try{localStorage.setItem('future-compass-v2',JSON.stringify({subjects:[...chosenSubjects],activities:[...chosenActivities],completed:[...completed],route}))}catch{}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-news-refresh'))refreshNews();if(b.dataset.newsFilter){newsFilter=b.dataset.newsFilter;render()}if(b.dataset.newsDomain){page='career';activeDomain=domains.some(d=>d.id===b.dataset.newsDomain)?b.dataset.newsDomain:'ai';render();document.querySelector('#domain-detail')?.scrollIntoView({behavior:'smooth',block:'start'})}if(b.dataset.domain&&activeDomain)document.querySelector('#domain-detail')?.scrollIntoView({behavior:'smooth',block:'start'});if(b.dataset.subject||b.dataset.activity||b.dataset.route)saveProgress()});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]'))saveProgress()});
render();refreshNews();
